import adopciones.models
from django.db import migrations, models
from django.utils import timezone


def normalizar_chips_y_bajas(apps, schema_editor):
    """Convierte chips antiguos CHIP-XXXX-XXXXX a 15 dígitos ISO y fecha de baja."""
    Mascota = apps.get_model("adopciones", "MascotaRescatada")
    hoy = timezone.localdate()

    for mascota in Mascota.objects.all().only(
        "id", "codigo_chip", "estado_adopcion", "actualizado_en", "fecha_baja"
    ):
        cambios = []
        digits = re.sub(r"\D", "", mascota.codigo_chip or "")[-15:].zfill(15)
        if mascota.codigo_chip != digits:
            mascota.codigo_chip = digits
            cambios.append("codigo_chip")
        if (
            mascota.estado_adopcion == "Fallecido"
            and mascota.fecha_baja is None
        ):
            mascota.fecha_baja = (
                mascota.actualizado_en.date() if mascota.actualizado_en else hoy
            )
            cambios.append("fecha_baja")
        if cambios:
            mascota.save(update_fields=cambios)


